        ret
;-----------------------------------------------------------------------------
; inp_                                                         1396D3  library
; Run-time library inp: reads a byte from an I/O port
;-----------------------------------------------------------------------------
inp_:
        push edx
        mov edx, eax
        sub eax, eax
        in al, dx
        pop edx
        ret
        db 00h,00h,00h,00h,00h
